def svg(case):
    nodes=case['nodes']; rels=case['rels']
    layouts={
      'M-001':[(30,90),(225,90),(420,90),(615,90),(810,90)],
      'M-002':[(25,85),(230,85),(435,85),(640,85),(845,85),(640,230)],
      'M-003':[(40,120),(250,45),(470,120),(690,45),(900,120)],
      'M-004':[(25,55),(225,20),(225,155),(470,90),(720,90)],
      'M-005':[(15,100),(150,100),(285,100),(420,35),(420,170),(590,100),(760,100),(930,100)],
      'M-006':[(25,85),(220,85),(415,85),(610,45),(610,190),(820,85)],
      'M-008':[(25,100),(225,100),(425,40),(425,190),(650,100)],
    }
    pos=layouts.get(case['code'],[(28+i*220,100) for i in range(len(nodes))])
    boxes=[]; arrows=[]
    for i,(label,(x,y)) in enumerate(zip(nodes,pos)):
        fill=['#f3f2fe','#ffffff','#f3f2fe','#fff8d4','#ffffff','#f3f2fe','#fff8d4','#ffffff'][i%8]
        boxes.append(f'<g data-architecture-node="{i+1}" data-architecture-node-id="n{i+1}"><rect x="{x}" y="{y}" width="142" height="82" rx="16" fill="{fill}" stroke="#4c30a5" stroke-width="2"/><text x="{x+12}" y="{y+32}" font-size="15" font-weight="700" fill="#0b004a">{escape(label)}</text><text x="{x+12}" y="{y+59}" font-size="12" fill="#475061">{"em desenho" if i and i<len(nodes)-1 else "fronteira"}</text></g>')
        if i<len(nodes)-1:
            nx,ny=pos[i+1]
            arrows.append(f'<g data-architecture-relation="r{i+1}" data-architecture-relation-label="{escape(rels[i])}" data-architecture-relation-from="n{i+1}" data-architecture-relation-to="n{i+2}"><path d="M{x+142} {y+41} C{x+168} {y+41},{nx-26} {ny+41},{nx} {ny+41}" stroke="#4c30a5" stroke-width="3" fill="none" marker-end="url(#arrow)"/><text x="{min(x+150,nx-10)}" y="{min(y,ny)+22}" font-size="11" fill="#0b004a">{escape(rels[i])}</text></g>')
    return f'''<div class="diagram" data-architecture-projection="topology" data-architecture-renderer="svg" data-architecture-source-backed="true" data-source="{SOURCE}" data-source-section="pedido funcional e limites" data-coverage="represented"><h2>Topologia de decisão e fronteiras</h2><p data-architecture-text-equivalent="true">{escape(case['arch'])}.</p><svg viewBox="0 0 1100 310" role="img" aria-label="Topologia de {escape(case['code'])}"><title>Topologia {escape(case['code'])}</title><desc>{escape(case['arch'])}</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#4c30a5"/></marker></defs><text x="24" y="285" font-size="13" font-weight="700" fill="#4c30a5">TOPOLOGIA ESPECÍFICA DO DOMÍNIO · RELAÇÕES DECLARADAS, NÃO CONTAGEM DE IMPLEMENTAÇÃO</text>{''.join(boxes)}{''.join(arrows)}</svg><div class="legend"><span data-architecture-legend-state="proposed">Mudança ou comportamento em desenho</span><span data-architecture-legend-state="preserved">Fronteira preservada</span><span data-architecture-legend-state="out-of-scope">Fora do escopo</span><span data-architecture-legend-state="discovery">Descoberta declarada</span></div></div>'''

def glance(c):
    labels=[escape(n[:16]) for n in c['nodes'][:6]]
    pts=[45+i*92 for i in range(len(labels))]
    lines=''.join(f'<path d="M{x+11} 34H{pts[i+1]-11}" stroke="#7fdfe0" stroke-width="3"/>' for i,x in enumerate(pts[:-1]))
    nodes=''.join(f'<g><circle cx="{x}" cy="34" r="11" fill="#7fdfe0"/><text x="{x}" y="61" text-anchor="middle" fill="#fff" font-size="10">{label}</text></g>' for x,label in zip(pts,labels))
    key=[escape(c['nodes'][0]), escape(c['nodes'][len(c['nodes'])//2]), escape(c['nodes'][-1])]
    mobile=''.join(f'<b>{x}</b>' for x in key)
    return f'<div class="hero-glance" aria-label="Resumo gráfico de {escape(c["code"])}"><span>LEITURA GRÁFICA DA ARQUITETURA</span><svg viewBox="0 0 560 72" role="img" aria-label="Fluxo resumido: {escape(c["arch"])}">{lines}{nodes}</svg><div class="hero-glance-mobile">{mobile}</div></div>'

def route(name, label, c):
    mini=glance(c) if name=='architecture' else ''
    common = f'''<div class="hero"><div class="hero-copy"><p class="eyebrow">{escape(label)} · {c['code']}</p><h1>{escape(c['title'])}</h1><p class="lede">{escape(c['thesis'])}</p>{mini}</div><aside class="decision"><p class="label">Decisão solicitada</p><strong>{escape(c['decision'])}</strong></aside></div><div class="intro"><article class="panel"><p class="label">Tese</p><p>{escape(c['thesis'])}</p></article><aside class="panel"><p class="label">Próximo passo</p><p>{escape(c['next'])}</p></aside></div>'''
    if name == 'architecture':
        visual = 'not-material' if c['code']=='M-007' else 'material'
        reason = 'O pedido descreve uma jornada operacional e nenhum backend novo; a visualização equivalente evita fingir subarquitetura.' if visual=='not-material' else ''
        topo = svg(c) if visual=='material' else f'''<div class="diagram"><h2>Jornada visual equivalente, não uma arquitetura inventada</h2><div class="flow">{''.join(f'<article><strong>{escape(n)}</strong><p>{"passo de serviço público" if i else "início da jornada"}</p></article>' for i,n in enumerate(c['nodes']))}</div><p><strong>Razão de proporcionalidade:</strong> {reason}</p></div>'''
        states=''.join(f'<article class="card" data-architecture-surface="s{i}"><p class="label">Superfície {i}</p><h3>{escape(n)}</h3><p>{"Fronteira preservada — API existente" if c["code"]=="M-007" and n=="API catálogo" else ("Proposta ou mudança de comportamento" if i in (2,3,4) else "Fronteira preservada")}</p></article>' for i,n in enumerate(c['nodes'],1))
        return f'''<section class="route" id="architecture" data-route="architecture" data-architecture-visual="{visual}" data-architecture-visual-reason="{escape(reason)}">{common}{topo}<div class="diagram" data-architecture-projection="surface-map" data-architecture-source-backed="true" data-source="{SOURCE}" data-source-section="pedido funcional" data-coverage="synthesized" data-architecture-unit="superfícies nomeadas no pedido"><h2>Mapa de superfícies, com unidade honesta</h2><p>{escape(c['surface'])}</p><div class="metrics">{states}</div><p><strong>Leitura correta:</strong> a unidade conta relações/superfícies declaradas, nunca arquivos, linhas, capacidade ou prazo.</p></div><div class="diagram" data-architecture-projection="zoom" data-architecture-source-backed="true" data-source="{SOURCE}" data-source-section="limites e decisões obrigatórias" data-coverage="represented" data-architecture-zoom-status="supported" data-architecture-zoom-target="fluxo material declarado"><h2>Zoom da fronteira que realmente muda</h2><p>{escape(c['zoom'])}</p><div class="flow">{''.join(f'<article><strong>{i:02d}</strong><p>{escape(t)}</p></article>' for i,t in enumerate(c['zoom'].split(' → '),1))}</div></div><div class="route-footer"><strong>Limite explícito:</strong> {escape(c['limit'])}</div></section>'''
    if name=='overview': body=f'<div class="pillars"><article class="card"><p class="label">Valor</p><h3>Uma decisão com fronteira</h3><p>{escape(c["decision"])}</p></article><article class="card"><p class="label">Pilar</p><h3>Fonte antes de forma</h3><p>A visualização torna relações declaradas legíveis sem criar precisão técnica.</p></article><article class="card"><p class="label">Limite</p><h3>Recorte consciente</h3><p>{escape(c["limit"])}</p></article></div>'
    elif name=='scope': body=f'<div class="pillars"><article class="card"><h3>Incluído</h3><p>{escape(c["arch"])}</p></article><article class="card"><h3>Não incluído</h3><p>{escape(c["limit"])}</p></article><article class="card"><h3>Próxima redução de risco</h3><p>{escape(c["next"])}</p></article></div>'
    elif name=='impact': body=f'<div class="pillars"><article class="card"><h3>Pessoas e operação</h3><p>{escape(c["impact"])}</p></article><article class="card"><h3>O que muda</h3><p>{escape(c["thesis"])}</p></article><article class="card"><h3>O que não prometemos</h3><p>{escape(c["limit"])}</p></article></div>'
    elif name=='execution':
        steps = ''.join(f"<article><strong>{i:02d} · etapa</strong><p>{escape(t)}</p></article>" for i,t in enumerate([c['next'],c['zoom'],c['limit']],1))
        body=f'<div class="flow">{steps}</div>'
    elif name=='validation': body=f'<div class="pillars"><article class="card"><h3>Contrato</h3><p>Testar relações, autorização, estados e recuperação definidos no pedido.</p></article><article class="card"><h3>Render e acessibilidade</h3><p>Inspecionar a rota em desktop/mobile, sem JavaScript e em impressão.</p></article><article class="card"><h3>Julgamento independente</h3><p>Separar checks objetivos de avaliação contextual; não converter ausência de evidência em aprovação.</p></article></div>'
    elif name=='evolution': body=f'<div class="flow"><article><strong>Registrar</strong><p>Conservar origem, estado e motivo de mudança onde o pedido exige auditoria.</p></article><article><strong>Recuperar</strong><p>{escape(c["zoom"])}</p></article><article><strong>Rever</strong><p>{escape(c["next"])}</p></article></div>'
    else: body=f'<div class="pillars"><article class="card"><h3>Fonte factual</h3><p>{escape(c["code"])} em <code>{SOURCE}</code>.</p></article><article class="card"><h3>Design</h3><p>Guia Pearson local: tipografia, navy/lavender, composição, contraste e logo.</p></article><article class="card"><h3>Não adoção</h3><p>Referência de laboratório descartável. Não altera T-004, HTML histórico nem fonte canônica.</p></article></div>'
    return f'<section class="route" id="{name}" data-route="{name}">{common}{body}<div class="route-footer"><strong>Limite:</strong> {escape(c["limit"])}</div></section>'

def document(c):
    nav=''.join(f'<a href="?view={k}" data-view="{k}">{v}</a>' for k,v in ROUTES)
    routes=''.join(route(k,v,c) for k,v in ROUTES)
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c['code']} · referência visual descartável</title>{CSS}</head><body><header class="top"><div class="bar"><a class="brand" href="?view=overview" aria-label="Pearson — referência visual"><img src="../../../.harness/assets/brand/pearson-logo-white.png" alt="Pearson" width="175" height="53"></a><span class="product">Brief executivo · laboratório visual</span></div></header><div class="notice"><p><strong>Referência descartável de SPEC 024 T-003.</strong> Não canônica; não adota nem altera o corpus T-004 ou HTMLs históricos.</p></div><main class="main"><nav class="route-nav" aria-label="Subpáginas">{nav}</nav>{routes}</main><footer class="footer"><p>{c['code']} · fonte factual: <code>{SOURCE}</code>. Design: <code>.harness/references/pearson-design.md</code>. Diagramas são SVG/HTML fonte-apoiados, não imagens geradas.</p></footer><script>(()=>{{const ok={str([x[0] for x in ROUTES])};const routes=[...document.querySelectorAll('[data-route]')],links=[...document.querySelectorAll('[data-view]')];function set(v,focus){{v=ok.includes(v)?v:'overview';routes.forEach(x=>x.hidden=x.dataset.route!==v);links.forEach(x=>x.setAttribute('aria-current',x.dataset.view===v?'page':'false'));document.title='{c['code']} · '+links.find(x=>x.dataset.view===v).textContent+' · referência visual';if(focus){{scrollTo(0,0);document.querySelector('#'+v+' h1').focus({{preventScroll:true}})}}}}set(new URLSearchParams(location.search).get('view'));links.forEach(a=>a.onclick=e=>{{e.preventDefault();history.pushState({{}},'',a.href);set(a.dataset.view,true)}});addEventListener('popstate',()=>set(new URLSearchParams(location.search).get('view'),true));}})();</script></body></html>'''

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    for c in CASES:
        (OUT / f"{c['id']}-reference.html").write_text(document(c), encoding="utf-8")
    (OUT / 'README.md').write_text("# Referências heterogêneas descartáveis — SPEC 024 T-003\n\nOito HTMLs locais e independentes, compostos contra os pedidos M-001…M-008. São evidência visual descartável: não promovem nem substituem `testes/mock-runs/20260831-spec023-t004-r1`, SPEC 023 ou fontes canônicas. Cada arquivo contém oito subpáginas `?view=` e usa o logo Pearson local. Arquitetura material usa SVG fonte-apoiado; M-007 declara jornada operacional `not-material` e explica por quê.\n", encoding='utf-8')
if __name__ == '__main__': main()
